head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[$p > M > hideProcessMessage]<br/>$p.showProcessMessage() 메소드로 표시된 프로세스 창(Process Message Layer)을 숨깁니다.",
    "validation" : [
        "showProcessMessage() 메소드로 표시된 프로세스 창을 숨겨야 합니다.",
        "Submission, ajax, Excel download 등의 기능으로 표시되는 프로세스 창과는 독립적으로 동작해야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_showProcessMessage_onclick = function () {
    $p.showProcessMessage("처리 중입니다...");
    wf_body_bottom.getObj("scwin").setReturnValue("showProcessMessage 실행");

    // 3초 후 자동 숨김
    setTimeout(function () {
        $p.hideProcessMessage();
        wf_body_bottom.getObj("scwin").setReturnValue("hideProcessMessage 자동 실행 (2초 후)");
    }, 2000);
}



scwin.btn_hideProcessMessage_onclick = function () {
    $p.hideProcessMessage();
    wf_body_bottom.getObj("scwin").setReturnValue("hideProcessMessage 실행");
}
